{
  "name": "Weiss LabEvent气候试验箱",
  "name_en": "Weiss LabEvent Climate Chamber",
  "manufacturer": "Weiss",
  "description": "用于实验室环境应力与温控测试的气候试验箱，可读取和设定箱内温度，并控制手动模式、冷凝保护、压缩空气和空气干燥等功能。",
  "description_en": "A climate chamber for laboratory environmental stress and temperature-control testing. It can read and set chamber temperature and control manual mode, condensation protection, compressed air, and air drying functions.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化气候试验箱连接",
      "description_en": "initialize the climate chamber connection"
    },
    {
      "action_name": "auto-query",
      "description": "发送原始命令并读取响应",
      "description_en": "send a raw command and read the response"
    },
    {
      "action_name": "auto-get_info",
      "description": "获取设备信息",
      "description_en": "get device information"
    },
    {
      "action_name": "auto-get_status",
      "description": "获取设备状态",
      "description_en": "get device status"
    },
    {
      "action_name": "auto-start_manual_mode",
      "description": "启动手动模式",
      "description_en": "start manual mode"
    },
    {
      "action_name": "auto-stop_manual_mode",
      "description": "停止手动模式",
      "description_en": "stop manual mode"
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取箱内温度",
      "description_en": "get chamber temperature"
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置箱内温度目标值",
      "description_en": "set the chamber temperature target"
    },
    {
      "action_name": "auto-get_temperature_setpoint",
      "description": "获取温度设定值",
      "description_en": "get the temperature setpoint"
    },
    {
      "action_name": "auto-get_condensation_protection",
      "description": "获取冷凝保护设置",
      "description_en": "get condensation protection setting"
    },
    {
      "action_name": "auto-set_condensation_protection",
      "description": "设置冷凝保护",
      "description_en": "set condensation protection"
    },
    {
      "action_name": "auto-get_compressed_air",
      "description": "获取压缩空气设置",
      "description_en": "get compressed air setting"
    },
    {
      "action_name": "auto-set_compressed_air",
      "description": "设置压缩空气",
      "description_en": "set compressed air"
    },
    {
      "action_name": "auto-get_air_dryer",
      "description": "获取空气干燥设置",
      "description_en": "get air dryer setting"
    },
    {
      "action_name": "auto-set_air_dryer",
      "description": "设置空气干燥",
      "description_en": "set air dryer"
    }
  ],
  "tag_hints": [
    "climate chamber",
    "environmental testing",
    "temperature control",
    "condensation protection",
    "compressed air",
    "air dryer",
    "manual mode"
  ]
}

